using System.Threading.Tasks; using OrderFlow.MVC.Data; using OrderFlow.MVC.Models;
namespace OrderFlow.MVC.Services { public class AuditService { private readonly OrderFlowDbContext _db; public AuditService(OrderFlowDbContext db) { _db = db; } public async Task LogAsync(int? userId, string entityType, string entityId, AuditAction action, string detail) { _db.AuditEvents.Add(new AuditEvent { UserId = userId, EntityType = entityType, EntityId = entityId, Action = action, Detail = detail }); await _db.SaveChangesAsync(); } } }
